/* 第03轮：原图媒体一次保存，裁切/文字块/归并可追溯；没有OCR调用。 */
window.createCimoraImportModel=function(M,S){
  const Q=M.comic,clone=M.clone,session=new Map();M.db.importMedia??={};const media=M.db.importMedia;
  const data=id=>media[id]?.data||session.get(id)||null;
  const storage=id=>media[id]?.data?'saved':session.has(id)?'session':'reconnect';
  const blocked=c=>Q.blocked(c);
  function ensure(c){const d=c.e.importDraft;if(!d)return null;d.files??=[];d.entities??=[];d.archivedPanels??=[];d.revision??=0;d.status??='pending';const moved=[];for(const f of d.files){f.id??=S.id('page');f.origin??='upload';f.version??=1;if(!f.mediaId){f.mediaId=S.id('original');media[f.mediaId]={id:f.mediaId,name:f.name,size:f.size,type:f.type,width:f.width||0,height:f.height||0,digest:f.digest||'',data:f.data||null};delete f.data;moved.push(f.mediaId);}}if(moved.length)persist(c,moved);return d;}
  function persist(c,newMedia=[]){const ok=M.save();if(ok===false){for(const id of newMedia){if(media[id]?.data){session.set(id,media[id].data);media[id].data=null;}}c.e.importDraft.persistenceError=true;M.save();return false;}c.e.importDraft.persistenceError=false;return true;}
  function touch(c,b){const d=ensure(c);d.revision++;d.status='review';delete d.confirmedRevision;c.e.reviewChecks=[false,false,false];if(b){b.version++;b.comic.revision++;}c.e.script=summary(c);persist(c);}
  function addPages(c,files){if(blocked(c))return blocked(c);const d=ensure(c),added=[];for(const input of files){const f=clone(input),id=S.id('original'),page={id:S.id('page'),mediaId:id,name:f.name,size:f.size,type:f.type,origin:f.origin==='example'?'example':'upload',sampleKey:f.sampleKey||null,version:1};const total=d.files.reduce((n,p)=>n+(media[p.mediaId]?.size||0),0);media[id]={id,name:f.name,size:f.size,type:f.type,width:f.width||0,height:f.height||0,digest:f.digest||'',data:null};if(f.data){if(f.size<=700000&&total+f.size<=1500000)media[id].data=f.data;else session.set(id,f.data);}d.files.push(page);added.push(id);}d.revision++;d.status='pending';delete d.confirmedRevision;persist(c,added);return null;}
  function reconnect(c,pageId,f){if(blocked(c))return blocked(c);const d=ensure(c),p=d.files.find(p=>p.id===pageId),m=p&&media[p.mediaId];if(!m)return '原图不存在';if(m.digest&&m.digest!==f.digest||m.name!==f.name||m.size!==f.size)return '所选文件与原图不符，请选择同一原图，或作为新页面追加';if(!f.data)return '无法读取图片';m.width=f.width;m.height=f.height;m.digest=f.digest||m.digest;if(f.size<=700000&&d.files.reduce((n,p)=>n+(media[p.mediaId]?.size||0),0)<=1500000)m.data=f.data;else session.set(m.id,f.data);persist(c,[m.id]);return null;}
  function sort(c){const d=ensure(c),order=new Map(d.files.map((p,i)=>[p.id,i]));c.e.boards.sort((a,b)=>(order.get(a.importSource.parts[0].pageId)-order.get(b.importSource.parts[0].pageId))||a.importOrder-b.importOrder);const counts={};for(const b of c.e.boards){const page=b.importSource.parts[0].pageId;b.importOrder=counts[page]||0;counts[page]=(counts[page]||0)+1;}}
  function valid(m,r){return m?.width>0&&m.height>0&&[r.x,r.y,r.w,r.h].every(Number.isFinite)&&r.x>=0&&r.y>=0&&r.w>=1&&r.h>=1&&r.x+r.w<=m.width&&r.y+r.h<=m.height;}
  function extract(c,b){const q=b.comic,image={id:S.id('import-image'),version:q.images.length+1,status:'ready',provenance:'original-extract',parts:clone(b.importSource.parts),input:{action:b.action,shot:b.shot,cast:clone(q.cast),scene:clone(q.scene),outfit:q.outfit},prototype:false};q.images.unshift(image);q.adoptedId=image.id;b.approved=true;}
  function sync(c,b){const d=ensure(c),entities=d.entities;for(const t of b.textBlocks){const e=entities.find(x=>x.id===t.entityId);t.speakerId=e?.assetRef?.id||'';t.speakerName=e?.assetRef?.snapshot.name||e?.label||'未指定';}const q=b.comic;b.dialogue=b.textBlocks.filter(t=>t.type==='dialogue').map(t=>t.speakerName+'：'+t.text).join('\n');q.text={speakerId:'',speakerName:'多文字块',dialogue:b.dialogue,narration:b.textBlocks.filter(t=>t.type==='narration').map(t=>t.text).join('\n'),sfx:b.textBlocks.filter(t=>t.type==='sfx').map(t=>t.text).join('\n')};q.cast=entities.filter(e=>e.type==='角色'&&e.assetRef&&(e.panelId===b.id||b.textBlocks.some(t=>t.entityId===e.id))).map(e=>clone(e.assetRef)).filter((r,i,rs)=>rs.findIndex(x=>x.id===r.id)===i);q.scene=clone(entities.find(e=>e.type==='场景'&&e.panelId===b.id&&e.assetRef)?.assetRef||null);}
  function addPanel(c,pageId,r){if(blocked(c))return null;const d=ensure(c),p=d.files.find(p=>p.id===pageId),m=p&&media[p.mediaId];r=Object.fromEntries(Object.entries(r).map(([k,v])=>[k,Number(v)]));if(!p||!data(p.mediaId)||!valid(m,r))return null;const b={id:S.id('panel'),title:'原图分格 '+(c.e.boards.length+1),action:'',dialogue:'',shot:'待确认',art:0,version:1,approved:true,importOrder:c.e.boards.filter(b=>b.importSource.parts[0].pageId===pageId).length,textBlocks:[],importSource:{kind:'original-extract',parts:[{pageId:p.id,pageVersion:p.version,mediaId:p.mediaId,digest:m.digest,width:m.width,height:m.height,bounds:clone(r)}]}};c.e.boards.push(b);Q.ensure(c);b.comic.revision=1;extract(c,b);sort(c);touch(c,b);return b;}
  const panel=(c,id)=>c.e.boards.find(b=>b.id===id);
  function editBounds(c,id,index,r){if(blocked(c))return blocked(c);const b=panel(c,id),part=b?.importSource.parts[index];if(!part)return '分格不存在';r=Object.fromEntries(Object.entries(r).map(([k,v])=>[k,Number(v)]));if(!valid(media[part.mediaId],r))return '裁切边界超出原图，或宽高无效';part.bounds=clone(r);b.importSource.kind='original-extract';delete b.importSource.repair;extract(c,b);touch(c,b);return null;}
  function split(c,id){if(blocked(c))return null;const b=panel(c,id);if(!b||b.importSource.parts.length!==1)return null;const p=b.importSource.parts[0],r=p.bounds;if(r.h<2)return null;ensure(c).archivedPanels.push(clone(b));const top=Math.floor(r.h/2),bottom={x:r.x,y:r.y+top,w:r.w,h:r.h-top};editBounds(c,id,0,{...r,h:top});const n=addPanel(c,p.pageId,bottom);n.importOrder=b.importOrder+.5;n.title=b.title+' · 后半格';sort(c);touch(c,n);return n;}
  function merge(c,ids){if(blocked(c))return null;const bs=c.e.boards.filter(b=>ids.includes(b.id));if(bs.length<2)return null;const first=bs[0];ensure(c).archivedPanels.push(...bs.map(b=>clone(b)));first.importSource.parts=bs.flatMap(b=>clone(b.importSource.parts));first.textBlocks=bs.flatMap(b=>b.textBlocks);first.action=bs.map(b=>b.action).filter(Boolean).join('\n');for(const e of ensure(c).entities)if(ids.includes(e.panelId))e.panelId=first.id;c.e.boards=c.e.boards.filter(b=>b===first||!ids.includes(b.id));sync(c,first);extract(c,first);touch(c,first);return first;}
  function movePage(c,id,dir){if(blocked(c))return;const fs=ensure(c).files,i=fs.findIndex(f=>f.id===id),j=i+dir;if(i<0||j<0||j>=fs.length)return;[fs[i],fs[j]]=[fs[j],fs[i]];sort(c);touch(c);}
  function movePanel(c,id,dir){if(blocked(c))return;const b=panel(c,id),same=c.e.boards.filter(x=>x.importSource.parts[0].pageId===b.importSource.parts[0].pageId),i=same.indexOf(b),other=same[i+dir];if(!other)return;[b.importOrder,other.importOrder]=[other.importOrder,b.importOrder];sort(c);touch(c);}
  function addBlock(c,id,v={}){if(blocked(c))return null;const b=panel(c,id);if(!b)return null;const t={id:S.id('text-block'),originalText:String(v.text||''),text:String(v.text||''),type:['dialogue','narration','sfx'].includes(v.type)?v.type:'dialogue',entityId:v.entityId||'',origin:v.origin||'manual',status:'待核对'};b.textBlocks.push(t);sync(c,b);touch(c,b);return t;}
  function editBlock(c,id,blockId,v){if(blocked(c))return blocked(c);const b=panel(c,id),t=b?.textBlocks.find(t=>t.id===blockId);if(!t)return '文字块不存在';for(const k of ['text','entityId'])if(k in v)t[k]=String(v[k]);if(['dialogue','narration','sfx'].includes(v.type))t.type=v.type;t.status='人工校正';sync(c,b);touch(c,b);return null;}
  function moveBlock(c,id,blockId,dir){if(blocked(c))return;const b=panel(c,id),i=b.textBlocks.findIndex(t=>t.id===blockId),j=i+dir;if(j<0||j>=b.textBlocks.length)return;[b.textBlocks[i],b.textBlocks[j]]=[b.textBlocks[j],b.textBlocks[i]];sync(c,b);touch(c,b);}
  function addEntity(c,id,type,label){if(blocked(c))return null;const e={id:S.id('appearance'),panelId:id,type:type==='场景'?'场景':'角色',label:String(label||'角色A'),assetRef:null,provenance:'original-reference'};ensure(c).entities.push(e);const b=panel(c,id);sync(c,b);touch(c,b);return e;}
  function mergeEntities(c,ids,v){if(blocked(c))return null;const es=ensure(c).entities.filter(e=>ids.includes(e.id));if(!es.length||es.some(e=>e.type!==es[0].type))return null;const a=v.assetId?S.state.assets.find(a=>a.id===v.assetId&&a.projectId===c.p.id&&a.type===es[0].type):Q.addAsset(c,{type:es[0].type,name:v.name||es[0].label,desc:'原图引用/人工归并；未执行人物抠图或场景分离。'});if(!a)return null;a.importProvenance??={kind:'original-reference',appearances:[]};for(const e of es){if(!a.importProvenance.appearances.includes(e.id))a.importProvenance.appearances.push(e.id);e.assetRef={id:a.id,version:a.version,snapshot:Q.assetVersion(c,a.id,a.version)};}for(const b of c.e.boards){sync(c,b);touch(c,b);}return a;}
  function editPanel(c,id,v){if(blocked(c))return blocked(c);const b=panel(c,id);for(const k of ['title','action','shot'])if(k in v)b[k]=String(v[k]);touch(c,b);return null;}
  function repair(c,id){if(blocked(c))return blocked(c);const b=panel(c,id);b.importSource.kind='repair-simulation';b.importSource.repair={status:'pending',notice:'仅登记去字修复模拟，未实际移除原图文字；当前仍使用原图裁切。'};b.comic.images.unshift({id:S.id('repair'),version:b.comic.images.length+1,status:'pending',provenance:'repair-simulation',parts:clone(b.importSource.parts),notice:b.importSource.repair.notice});touch(c,b);return null;}
  function summary(c){return c.e.boards.map((b,i)=>`${i+1}. ${b.title}：${b.action||'剧情待补充'}${b.textBlocks?.length?'\n'+b.textBlocks.map((t,j)=>`  ${j+1}) ${t.type==='dialogue'?'对白':t.type==='narration'?'旁白':'音效字'} / ${t.speakerName||'未指定'}：${t.text}`).join('\n'):''}`).join('\n\n');}
  function pending(c){const d=ensure(c),out=[];for(const p of d.files)if(!data(p.mediaId))out.push(p.name+'：原图需重连');for(const b of c.e.boards){if(!b.action.trim())out.push(b.title+'：剧情待补充');if(!b.textBlocks.length)out.push(b.title+'：未录入文字，请确认是否无字');if(b.textBlocks.some(t=>!t.text.trim()))out.push(b.title+'：有空文字块');if(b.textBlocks.some(t=>t.type==='dialogue'&&!t.speakerId))out.push(b.title+'：有对白说话人未归并');if(b.importSource.repair)out.push(b.title+'：去字修复未执行');}for(const e of d.entities)if(!e.assetRef)out.push(e.label+'：尚未归并到项目资产');return out;}
  function confirm(c,v={}){if(blocked(c))return blocked(c);const d=ensure(c);if(!c.e.boards.length)return '先手工切格或明确选择模拟示例';if(d.files.some(p=>!data(p.mediaId)))return '原图需重连，不能确认资料可用';if(pending(c).length&&!v.acceptPending)return '请处理待核对项，或明确接受这些待确认项继续';d.status='confirmed';d.confirmedRevision=d.revision;d.reviewSummary=String(v.summary??summary(c));c.e.script=d.reviewSummary;persist(c);return null;}
  function adapt(c){const d=ensure(c);if(d.status!=='confirmed'||d.confirmedRevision!==d.revision)return {error:'请先检查并确认当前剧情与资料'};if(d.files.some(p=>!data(p.mediaId)))return {error:'原图需重连'};const ep=M.production.addEpisode(c.p,c.c.title+' · 漫画改编',[c.c.id]);return {context:M.activate(c.p.id,ep.id)};}
  function preset(c){const d=ensure(c);if(!d.files.length||d.files.some(p=>p.origin!=='example'||p.sampleKey!=='letters-v1'))return '仅明确选择的模拟示例可使用预置解析';if(c.e.boards.length)return '已有分格，不覆盖现有解析';const a=d.files[0],z=d.files[1]||a,b=addPanel(c,a.id,{x:0,y:0,w:800,h:600}),n=addPanel(c,a.id,{x:0,y:600,w:800,h:600}),last=addPanel(c,z.id,{x:0,y:0,w:800,h:600});if(!b||!n||!last)return '示例原图不完整';b.action='戴围巾的人推门进入书店。';n.action='她把信放到桌上。';last.action='窗外的雨停了。';const e1=addEntity(c,b.id,'角色','角色A'),e2=addEntity(c,n.id,'角色','角色B');addEntity(c,b.id,'场景','场景A');addEntity(c,n.id,'场景','场景B');addBlock(c,b.id,{text:'你回来了？',entityId:e1.id,origin:'preset-simulation'});addBlock(c,b.id,{text:'这封信给你。',entityId:e2.id,origin:'preset-simulation'});addBlock(c,n.id,{text:'她把旧信放下。',type:'narration',origin:'preset-simulation'});addBlock(c,last.id,{text:'雨停了。',type:'narration',origin:'preset-simulation'});d.parseMode='preset-simulation';touch(c);return null;}
  const oldSource=Q.source;Q.source=b=>{const base=oldSource(b);return b.importSource?{...base,textBlocks:clone(b.textBlocks||[]),importSource:clone(b.importSource)}:base;};
  const oldEdit=Q.editPanel;Q.editPanel=(c,id,v)=>panel(c,id)?.importSource&&('dialogue'in v||'narration'in v||'sfx'in v)?'此格包含多个文字块，请到解析校正逐条编辑，原文字不会合并覆盖':oldEdit(c,id,v);
  const oldCreate=M.adaptation.create;M.adaptation.create=v=>{const c=oldCreate(v.source==='comic'?{...v,files:[]}:v);if(c.e.importDraft){addPages(c,v.files||[]);}return c;};
  const oldEpisode=M.production.addEpisode;M.production.addEpisode=(p,title,ids=[])=>{for(const id of ids){const cc=M.context(p.id,id),d=cc.e.importDraft;if(d&&(d.status!=='confirmed'||d.confirmedRevision!==d.revision||d.files.some(f=>!data(f.mediaId))))throw new Error('上传漫画需先确认当前剧情与资料，并重连缺失原图');}return oldEpisode(p,title,ids);};
  M.imports={ensure,data,storage,media,addPages,reconnect,addPanel,editBounds,split,merge,movePage,movePanel,addBlock,editBlock,moveBlock,addEntity,mergeEntities,editPanel,repair,summary,pending,confirm,adapt,preset,panel,blocked};return M;
};

